import {efficiencyHeatmap,efficiencyScale} from './heat-map.js?v=1.6.0';
import {operatingPointLabel,orderedOperatingPoints,orderedCombinations} from './result-view.js?v=1.6.0';
import {CATEGORIES,LABELS} from './engine.js?v=1.6.0';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number.isFinite(v)?Number(v.toPrecision(5)).toString():'—';
const colors=['#2980b9','#8e44ad','#e67e22','#c0392b','#16a085','#7f8c8d','#2c3e50'];
export function stackedBars(items,keys=CATEGORIES,labels=LABELS,unit='W'){if(!items.length)return '<p>No valid results.</p>';let out='';for(let offset=0;offset<items.length;offset+=12){let rows=items.slice(offset,offset+12),max=Math.max(1e-12,...rows.map(r=>keys.reduce((s,k)=>s+(r.values[k]||0),0))),width=1100,left=460,right=80,height=rows.length*36+45;out+=`<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Loss comparison in watts">`;rows.forEach((r,j)=>{let y=j*36+22,x=left,total=0;out+=`<text x="${left-10}" y="${y+14}" text-anchor="end">${esc(r.label.length>72?r.label.slice(0,69)+'…':r.label)}<title>${esc(r.label)}</title></text>`;keys.forEach((k,z)=>{let value=r.values[k]||0,w=value/max*(width-left-right);out+=`<rect x="${x}" y="${y}" width="${w}" height="22" fill="${colors[z%colors.length]}"><title>${esc(r.label+' · '+(labels[k]||k)+': '+n(value)+' '+unit)}</title></rect>`;x+=w;total+=value;});out+=`<text x="${x+7}" y="${y+15}">${n(total)} ${esc(unit)}</text>`;});out+=`<text x="${left}" y="${height-4}">0 ${esc(unit)}</text><text x="${width-right}" y="${height-4}" text-anchor="end">${n(max)} ${esc(unit)}</text></svg>`;}return out+`<div class="legend">${keys.map((k,j)=>`<span><i style="background:${colors[j%colors.length]}"></i>${esc(labels[k]||k)}</span>`).join('')}</div>`;}
const groups=rows=>{const g=new Map();orderedOperatingPoints(rows).forEach(r=>{let k=r.vin+' / '+r.vout+' V';let a=g.get(k)||[];a.push(r);g.set(k,a);});return [...g];};
export function pointLossCharts(rows){return groups(rows.filter(r=>r.valid)).map(([pair,rs])=>`<h3>Vin / Vout: ${esc(pair)}</h3>${stackedBars(rs.sort((a,b)=>a.outputPower-b.outputPower).map(r=>({label:operatingPointLabel(r),values:r.categories})))}`).join('');}
function exactMap(rows,axis){return efficiencyHeatmap(rows,axis,efficiencyScale(rows),true);}
export function comparisonVisuals(project,results,options={}){let out='';if(options.comparisonCharts!==false){out='<h2>Ranking: mean efficiency and mean loss</h2>';out+=stackedBars(orderedCombinations(results.ranking).filter(r=>r.valid).map(r=>({label:'Combination '+r.combination,values:{loss:r.meanLoss}})),['loss'],{loss:'Mean component loss'});out+=stackedBars(orderedCombinations(results.ranking).filter(r=>r.valid).map(r=>({label:'Combination '+r.combination,values:{eta:r.meanEfficiency}})),['eta'],{eta:'Mean efficiency'},'%');out+='<div class="table-wrap"><table><thead><tr><th>Combination</th><th>Mean efficiency [%]</th><th>Worst efficiency [%]</th></tr></thead><tbody>'+orderedCombinations(results.ranking).map(r=>`<tr><td>${r.combination}</td><td>${n(r.meanEfficiency)}</td><td>${n(r.worstEfficiency)}</td></tr>`).join('')+'</tbody></table></div>';}
for(const rank of orderedCombinations(results.ranking)){const rows=orderedOperatingPoints(results.rows.filter(r=>r.combination===rank.combination)),valid=rows.filter(r=>r.valid);out+=`<section class="report-section"><h2>Combination ${rank.combination}: ${esc(rank.parts)}</h2>${options.lossCharts!==false?`<h3>Loss breakdown at every operating point</h3>${pointLossCharts(rows)}`:''}`;const ids=project.instances.map(i=>i.id),labels=Object.fromEntries(project.instances.map(i=>[i.id,i.name]));if(options.componentCharts!==false){out+=`<h3>Loss by component at every operating point</h3>${stackedBars(valid.map(r=>({label:operatingPointLabel(r),values:Object.fromEntries(r.devices.filter(d=>d.valid).map(d=>[d.instanceId,d.total]))})),ids,labels)}`;for(const inst of project.instances){out+=`<h3>${esc(inst.name)}: loss categories at every operating point</h3>${stackedBars(valid.flatMap(r=>r.devices.filter(d=>d.valid&&d.instanceId===inst.id).map(d=>({label:operatingPointLabel(r)+' · '+d.part,values:d.categories}))))}`;}}if(options.maps!==false)out+=`<h3>Efficiency map: Vin versus output power [%]</h3>${exactMap(valid,'vin')}<h3>Efficiency map: Vout versus output power [%]</h3>${exactMap(valid,'vout')}<p class="caption">Exact available operating points. Missing cells remain unknown; repeated cells are averaged.</p>`;out+='</section>';}
if(options.alternatives!==false)for(const inst of project.instances){const seen=new Set(),items=[];for(const r of orderedOperatingPoints(results.rows))for(const d of r.devices){const key=r.waveformId+':'+d.candidateId;if(d.valid&&d.instanceId===inst.id&&!seen.has(key)){seen.add(key);items.push({label:operatingPointLabel(r)+' · '+d.part,values:d.categories});}}out+=`<section class="report-section"><h2>${esc(inst.name)}: all alternatives</h2>${stackedBars(items)}</section>`;}return out;}
